def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people_patches = image_patch.find("person")

    if not people_patches:
        return image_patch

    numeric_people = []

    for person in people_patches:
        description = person.simple_query("Describe yourself.")
        number_str = ''.join(filter(str.isdigit, description))

        try:
            number = float(number_str)
            numeric_people.append((person, number))
        except ValueError:
            continue

    if not numeric_people:
        return people_patches[0]

    _, closest_person = min(numeric_people, key=lambda x: abs(x[1] - 74))
    return closest_person

