def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    hats = image_patch.find("hat")
    shirts = image_patch.find("hard rock shirt")

    if not hats or not shirts:
        return image_patch

    hat = hats[0]
    shirt = shirts[0]

    overlapping_patches = []
    for h in hats:
        for s in shirts:
            if h.overlaps_with(s.left, s.lower, s.right, s.upper):
                overlapping_patches.append((h, s))

    if not overlapping_patches:
        return image_patch

    best_match = max(overlapping_patches, key=lambda x: x[0].horizontal_center + x[1].horizontal_center)
    return best_match[0]

