def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    shoe_patches = image_patch.find("sandal")
    glass_patches = image_patch.find("glass")

    if not man_patches or not shoe_patches or not glass_patches:
        return image_patch

    man_shoe_pairs = [(man, shoe) for man in man_patches for shoe in shoe_patches if is_between_3d(shoe, man, man)]
    man_glass_pairs = [(man, glass) for man in man_patches for glass in glass_patches if is_between_3d(glass, man, man)]

    valid_men = []
    for man, shoe in man_shoe_pairs:
        for man, glass in man_glass_pairs:
            if man == man:
                valid_men.append((man, min(distance_3d(shoe, glass), distance_3d(man, shoe), distance_3d(man, glass))))

    if not valid_men:
        return image_patch

    return min(valid_men, key=lambda x: x[1])[0]

